from subject import *

def raises_type(fn, kind):
    try:
        fn()
    except kind:
        return True
    return False

def rejects(fn):
    return raises_type(fn, ValueError)

def fails_then(count, result):
    state = [0]
    def operation():
        state[0] += 1
        if state[0] <= count:
            raise RuntimeError('transient')
        return result
    return operation

def count_nonretryable():
    state = [0]
    def operation():
        state[0] += 1
        raise ValueError('permanent')
    try:
        retry(operation, 3)
    except ValueError:
        pass
    return state[0]
assert utc_day('2026-03-02T00:01:00+12:00') == '2026-03-01'
assert utc_day('2026-03-02T23:59:00-12:00') == '2026-03-03'
assert utc_day('2026-12-04T12:00:00Z') == '2026-12-04'
assert utc_day('2026-02-03T12:00:00') == '2026-02-03'

