    state = [0]
    def operation():
        state[0] += 1
        if state[0] <= count:
            raise RuntimeError('transient')
        return result
    return operation

def count_nonretryable():
    state = [0]
    def operation():
        state[0] += 1
        raise ValueError('permanent')
    try:
        retry(operation, 3)
    except ValueError:
        pass
    return state[0]
